## Code Example

```javascript
// Pseudo-code: propagate tenantId in trace context and redact logs
import { trace, context } from '@opentelemetry/api';
function logWithTenant(tenantId, msg) {
  const span = trace.getSpan(context.active());
  span.setAttribute('tenant.id', tenantId);
  const redacted = redactPII(msg);
  console.log(`${tenantId} ${redacted}`);
}
```

